import heroImg from "../../images/cote_divoire.png";
import ndprImg from "../../images/ndpr.png";
import gdprImg from "../../images/gdpr.jpg";
import nimcImg from "../../images/nidologo.png";
import osiaImg from "../../images/osia.png";
import avatar1 from "../../images/avatar1.jpg";
import avatar2 from "../../images/avatar2.jpg";
import avatar3 from "../../images/avatar3.jpg";
import avatar4 from "../../images/avatar4.jpg";

import {
  HeroWrapper,
  HeroStrip,
  HeroBgImage,
  HeroContainer,
  HeroContent,
  HeroTag,
  HeroTitle,
  HeroSubtitle,
  HeroButtons,
  PrimaryBtn,
  SecondaryBtn,
  TrustIndicators,
  TrustItem,
  TrustIcon,
  TrustLabel,
  TrustTitle,
  TrustDesc,
  SocialProof,
  AvatarStack,
  Stars,
  HowSection,
  SectionHeading,
  SectionSub,
  StepsRow,
  StepCard,
  StepTop,
  StepNumber,
  StepIconBox,
  StepName,
  StepDesc,
  StepArrow,
  ServicesSection,
  CardsGrid,
  ServiceCard,
  ServiceIcon,
  ServiceName,
  ServiceDesc,
  ServicePrice,
  FeatureList,
  FeatureItem,
  ServiceBtn,
  LearnMoreLink,
  ViewAllLink,
  ComplianceSection,
  ComplianceInner,
  ComplianceText,
  ComplianceTitle,
  ComplianceDesc,
  ComplianceLogos,
  ComplianceBadge,
  CtaSection,
  CtaInner,
  CtaShield,
  CtaContent,
  CtaTitle,
  CtaDesc,
  CtaButton,
} from "./HomePage.elements";
const { useToken } = theme;

const Home = () => {
  const [ipAddress, setIpAddress] = useState(null);
  const [ipCountry, setIpCountry] = useState(null);
  const [servicePrices, setServicePrices] = useState(null);
  const dispatch = useDispatch();
  const history = useHistory();

  const { token } = useToken();
  const { isDark } = useTheme();
  const { t } = useLocale();
  const { bgContainer, text } = token;
  const ninVerify = useAuthRedirect("/verify/nin");
  const vehicleVerify = useAuthRedirect("/verify/vehicle");
  const residentVerify = useAuthRedirect("/verify/resident");

  useEffect(() => {
    const fetchIpAddress = async () => {
      // ============================================================
      // 🧪 TESTING OVERRIDE - Uncomment to use static IP/Country
      // ============================================================
      // When uncommented, bypasses all IP detection APIs
      // Comment out this entire section for normal operation
      // ============================================================
      const testIp = "41.202.219.255"; // Cote d'Ivoire IP
      const testCountry = "CI"; // Cote d'Ivoire
      const testCurrency = "XOF"; // West African CFA franc
      // For testing USD pricing, use:
      // const testIp = "8.8.8.8";           // US IP
      // const testCountry = "US";           // United States
      // const testCurrency = "USD";         // US Dollar
      setIpAddress(testIp);
      setIpCountry(testCountry);
      localStorage.setItem("IpAddress", testIp);
      localStorage.setItem("userCountry", testCountry);
      localStorage.setItem("currencyCheck", testCurrency);
      console.log(
        "🧪 Using test IP/Country:",
        testIp,
        testCountry,
        testCurrency,
      );
      return;
      // ============================================================

      // Try ipapi.co first — returns IP + country info in one call
      try {
        const response = await axios.get("https://ipapi.co/json/");
        const ip = response.data.ip;
        const country = response.data.country_code || response.data.country; // e.g. "CI" for Cote d'Ivoire
        setIpAddress(ip);
        localStorage.setItem("IpAddress", ip);
        setIpCountry(country);
        localStorage.setItem("userCountry", country || ""); // Store country in localStorage for other pages
        const currency = country === "CI" ? "XOF" : "USD";
        localStorage.setItem("currencyCheck", currency);
        return;
      } catch (error1) {
        console.error("Error fetching IP/country from ipapi.co:", error1);
      }

      // Fallback to ipbase.com for IP and country
      try {
        const response = await axios.get("https://api.ipbase.com/v1/json/");
        const ip = response.data.ip;
        const country = response.data.country_code || response.data.countryCode;
        setIpAddress(ip);
        localStorage.setItem("IpAddress", ip);
        if (country) {
          setIpCountry(country);
          localStorage.setItem("userCountry", country);
          const currency = country === "CI" ? "XOF" : "USD";
          localStorage.setItem("currencyCheck", currency);
        }
        return;
      } catch (error2) {
        console.error("Error fetching IP from both sources:", error2);
        // Both APIs failed - use default Cote d'Ivoire IP and country
        const defaultIp = "41.202.219.255";
        const defaultCountry = "CI";
        const defaultCurrency = "XOF";
        setIpAddress(defaultIp);
        setIpCountry(defaultCountry);
        localStorage.setItem("IpAddress", defaultIp);
        localStorage.setItem("userCountry", defaultCountry);
        localStorage.setItem("currencyCheck", defaultCurrency);
      }
    };

    fetchIpAddress();
  }, []);

  useEffect(() => {
    const fetchServicePrices = async () => {
      try {
        const response = await apiGet("/africa/countries/CI/service-prices");
        const services = response.data?.data || response.data || response;
        setServicePrices(Array.isArray(services) ? services : null);
      } catch (error) {
        console.error("Failed to fetch service prices:", error);
      }
    };
    fetchServicePrices();
  }, []);

  const login = useGoogleLogin({
    onSuccess: async (response) => {
      try {
        const payload = {
          accessToken: response.access_token,
          deviceToken: localStorage.getItem("clientToken"),
          ipAddress: ipAddress,
          deviceName: "Web app",
        };

        const res = await apiPost(`/openauth/google-login`, payload);
        const userData = res;
        Swal.fire({
          background: bgContainer,
          color: text,
          title: "Success",
          text: "Google login successful!",
          icon: "success",
          customClass: {
            confirmButton: "custom-swal-button",
          },
          allowOutsideClick: false,
          allowEscapeKey: false,
        });
        dispatch({
          type: "SIGN_IN",
          payload: userData,
        });
        dispatch(fetchUserProfile(userData.jwtToken));

        if (userData.jwtToken) {
          localStorage.setItem("IpAddress", ipAddress);
          history.push("/main-dashboard");
        } else {
          Swal.fire({
            background: bgContainer,
            color: text,
            title: "Error",
            text: "Login failed",
            icon: "error",
            customClass: {
              confirmButton: "custom-swal-button",
            },
            allowOutsideClick: false,
            allowEscapeKey: false,
          });
        }
      } catch (error) {
        console.error("Google login failed:", error);

        let errorMessage = "Google login failed. Please try again.";

        if (error.response) {
          console.error("Server responded with status:", error.response.status);
          if (error.response.data && error.response.data.message) {
            errorMessage = error.response.data.message;
          }
        } else if (error.request) {
          console.error("No response received from server:", error.request);
          errorMessage = "Network error. Please check your connection.";
        } else {
          console.error("Error setting up request:", error.message);
        }
        Swal.fire({
          background: bgContainer,
          color: text,
          title: "Error",
          text: errorMessage,
          icon: "error",
          customClass: {
            confirmButton: "custom-swal-button",
          },
          allowOutsideClick: false,
          allowEscapeKey: false,
        });
      }
    },
    // Add onError to handle potential issues with the popup itself, though less common for blocking.
    onError: (errorResponse) => {
      console.error("Google login error:", errorResponse);
      // This onError might catch some initial errors before the popup opens or if there's
      // an issue with the Google API configuration, but not directly a popup block.
    },
    // IMPORTANT: For redirect flow, you typically set 'flow: "auth-code"' and handle it differently.
    // However, if you want a redirect fallback for a *blocked popup*, you'd initiate the redirect yourself.
    // For a pure redirect flow, use 'flow: "popup"'. You would then send the code to your backend.
    // For this scenario, we're relying on the `login()` function's default popup behavior,
    // and falling back to a redirect if that specific popup fails.
  });

  useEffect(() => {
    const loadGoogleOneTap = () => {
      if (window.google && window.google.accounts?.id) {
        window.google.accounts.id.disableAutoSelect(); // ⛔ reset for dev

        window.google.accounts.id.initialize({
          client_id:
            "642042384169-d0uquoka9qll83ucfm8ck7esdvptknls.apps.googleusercontent.com",
          callback: (credentialResponse) => {
            login();
          },
          auto_select: true,
          cancel_on_tap_outside: false,
        });

        window.google.accounts.id.prompt((notification) => {
          if (notification.isNotDisplayed()) {
            console.warn(
              "⚠️ One Tap not displayed:",
              notification.getNotDisplayedReason(),
            );
            // Check specifically if the reason is 'popup_blocked'
            if (notification.getNotDisplayedReason() === "popup_blocked") {
              console.log(
                "Popup blocked. Initiating redirect for Google login.",
              );
              // Trigger Google login via redirect flow
              // This is the key change: manually construct the redirect URL
              const redirectUri = window.location.origin; // Or a specific redirect URL configured in your Google Cloud Console
              const authUrl =
                `https://accounts.google.com/o/oauth2/v2/auth?` +
                `client_id=${"642042384169-d0uquoka9qll83ucfm8ck7esdvptknls.apps.googleusercontent.com"}&` +
                `response_type=code&` + // Request an authorization code
                `scope=openid%20profile%20email&` + // Required scopes
                `redirect_uri=${encodeURIComponent(redirectUri)}&` +
                `access_type=offline&` + // If you need a refresh token
                `prompt=consent%20select_account`; // Force user to select account and consent

              window.location.href = authUrl; // Redirect the user
            }
          }
          if (notification.isSkippedMoment()) {
            console.warn(
              "⚠️ One Tap skipped:",
              notification.getSkippedReason(),
            );
          }
          if (notification.isDismissedMoment()) {
            console.warn(
              "⚠️ One Tap dismissed:",
              notification.getDismissedReason(),
            );
          }
        });
      }
    };

    const interval = setInterval(() => {
      if (window.google && window.google.accounts?.id) {
        loadGoogleOneTap();
        clearInterval(interval);
      }
    }, 100);
  }, []);

  // If you decide to handle the ID token from One Tap directly (Recommended for One Tap)
  // const handleOneTapCredential = async (idToken) => {
  //   try {
  //     const payload = {
  //       idToken: idToken, // Send the ID token directly
  //       deviceToken: localStorage.getItem("clientToken"),
  //       ipAddress: ipAddress,
  //       deviceName: "Web app",
  //     };
  //     const res = await apiPost(`/openauth/google-one-tap-login`, payload); // New backend endpoint for ID token
  //     // ... rest of your success logic (Swal, Redux dispatch, history.push)
  //   } catch (error) {
  //     console.error("One Tap login failed:", error);
  //     // ... error handling
  //   }
  // };

  const isAuthenticated = useSelector((state) => state.isAuthenticated);
  const ctaLink = isAuthenticated
    ? "/dashboard"
    : "/verification-login?redirect=/verify/nin";

  return (
    <>
      {/* ── Hero ── */}
      <HeroWrapper>
        <HeroBgImage src={heroImg} alt="e-citizen verification platform" />
        <HeroContainer>
          <HeroContent>
            <HeroTitle>
              {t("home.hero.titlePrefix")}{" "}
              <span
                style={{
                  color: "#FD7A00",
                  fontFamily: "inherit",
                  fontSize: "inherit",
                  fontWeight: "inherit",
                }}
              >
                {t("home.hero.titleCountry")}{" "}
              </span>
              {t("home.hero.titleSuffix")}
            </HeroTitle>
            <HeroSubtitle>{t("home.hero.subtitle")}</HeroSubtitle>
            <HeroButtons>
              <SecondaryBtn href="#services">
                {t("home.hero.verifyNationalId")} <FaArrowRight />
              </SecondaryBtn>
              <SecondaryBtn href="#services">
                {t("home.hero.checkVin")} <FaArrowRight />
              </SecondaryBtn>
            </HeroButtons>
            <TrustIndicators>
              <TrustItem>
                <TrustIcon>
                  <FaLock />
                </TrustIcon>
                <TrustLabel>
                  <TrustTitle>{t("home.trust.secureTitle")}</TrustTitle>
                  <TrustDesc>{t("home.trust.secureDesc")}</TrustDesc>
                </TrustLabel>
              </TrustItem>
              <TrustItem>
                <TrustIcon>
                  <FaBolt />
                </TrustIcon>
                <TrustLabel>
                  <TrustTitle>{t("home.trust.instantTitle")}</TrustTitle>
                  <TrustDesc>{t("home.trust.instantDesc")}</TrustDesc>
                </TrustLabel>
              </TrustItem>
              <TrustItem>
                <TrustIcon>
                  <FaShieldAlt />
                </TrustIcon>
                <TrustLabel>
                  <TrustTitle>{t("home.trust.compliantTitle")}</TrustTitle>
                  <TrustDesc>{t("home.trust.compliantDesc")}</TrustDesc>
                </TrustLabel>
              </TrustItem>
            </TrustIndicators>
            <SocialProof>
              <AvatarStack>
                <img src={avatar1} alt="user" />
                <img src={avatar2} alt="user" />
                <img src={avatar3} alt="user" />
                <img src={avatar4} alt="user" />
              </AvatarStack>
              {t("home.socialProof")}
            </SocialProof>
          </HeroContent>
        </HeroContainer>
      </HeroWrapper>
      <HeroStrip aria-hidden="true" />

      {/* ── How It Works ── */}
      <HowSection id="how-it-works">
        <SectionHeading>{t("home.how.title")}</SectionHeading>
        <SectionSub>{t("home.how.subtitle")}</SectionSub>
        <StepsRow>
          <StepCard>
            <StepTop>
              <StepNumber>1</StepNumber>
              <StepIconBox>
                <FaIdCard />
              </StepIconBox>
            </StepTop>
            <StepName>{t("home.how.step1Name")}</StepName>
            <StepDesc>{t("home.how.step1Desc")}</StepDesc>
          </StepCard>
          <StepArrow>
            <FaArrowRight />
          </StepArrow>
          <StepCard>
            <StepTop>
              <StepNumber>2</StepNumber>
              <StepIconBox>
                <FaUpload />
              </StepIconBox>
            </StepTop>
            <StepName>{t("home.how.step2Name")}</StepName>
            <StepDesc>{t("home.how.step2Desc")}</StepDesc>
          </StepCard>
          <StepArrow>
            <FaArrowRight />
          </StepArrow>
          <StepCard>
            <StepTop>
              <StepNumber>3</StepNumber>
              <StepIconBox>
                <FaShieldAlt />
              </StepIconBox>
            </StepTop>
            <StepName>{t("home.how.step3Name")}</StepName>
            <StepDesc>{t("home.how.step3Desc")}</StepDesc>
          </StepCard>
        </StepsRow>
      </HowSection>

      {/* ── Service Cards ── */}
      <ServicesSection id="services">
        <SectionHeading>{t("home.services.title")}</SectionHeading>
        <SectionSub>{t("home.services.subtitle")}</SectionSub>

        <CardsGrid>
          {/* Carte Nationale d'Identité (NNI) */}
          <ServiceCard>
            <ServiceIcon>
              <FaIdCard />
            </ServiceIcon>
            <ServiceName>{t("home.services.nin.name")}</ServiceName>
            <ServiceDesc>{t("home.services.nin.desc")}</ServiceDesc>
            <ServicePrice>
              {(() => {
                const s = Array.isArray(servicePrices)
                  ? servicePrices.find((x) => x.service === "National ID NNI")
                  : null;
                const isCI =
                  (ipCountry ||
                    localStorage.getItem("currencyCheck") ||
                    "USD") === "CI" ||
                  localStorage.getItem("currencyCheck") === "XOF";
                if (!s) return isCI ? "CFA —" : "$ —";
                return isCI
                  ? `CFA ${Number(s.price).toLocaleString()}`
                  : `$${Number(s.price2).toFixed(2)}`;
              })()}
            </ServicePrice>
            <FeatureList>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.ninLookup")}
              </FeatureItem>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.fullName")}
              </FeatureItem>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.photoId")}
              </FeatureItem>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.resultsMinutes")}
              </FeatureItem>
            </FeatureList>
            <ServiceBtn to={ninVerify}>
              {t("home.services.verifyNow")}
            </ServiceBtn>
            <LearnMoreLink to="/nin-verification">
              {t("home.services.learnMore")}{" "}
              <FaArrowRight style={{ fontSize: 11 }} />
            </LearnMoreLink>
          </ServiceCard>

          {/* Carte de Résident */}
          <ServiceCard>
            <ServiceIcon>
              <FaAddressCard />
            </ServiceIcon>
            <ServiceName>{t("home.services.resident.name")}</ServiceName>
            <ServiceDesc>{t("home.services.resident.desc")}</ServiceDesc>
            <ServicePrice>
              {(() => {
                const s = Array.isArray(servicePrices)
                  ? servicePrices.find((x) => x.service === "Residents ID")
                  : null;
                const isCI =
                  ipCountry === "CI" ||
                  localStorage.getItem("currencyCheck") === "XOF";
                if (!s) return isCI ? "CFA —" : "$ —";
                return isCI
                  ? `CFA ${Number(s.price).toLocaleString()}`
                  : `$${Number(s.price2).toFixed(2)}`;
              })()}
            </ServicePrice>
            <FeatureList>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.residentLookup")}
              </FeatureItem>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.residentStatus")}
              </FeatureItem>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.residentAddress")}
              </FeatureItem>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.resultsMinutes")}
              </FeatureItem>
            </FeatureList>
            <ServiceBtn to={residentVerify}>
              {t("home.services.verifyNow")}
            </ServiceBtn>
            <LearnMoreLink to="/nin-verification">
              {t("home.services.learnMore")}{" "}
              <FaArrowRight style={{ fontSize: 11 }} />
            </LearnMoreLink>
          </ServiceCard>

          {/* Vérification VIN */}
          <ServiceCard>
            <ServiceIcon>
              <FaCar />
            </ServiceIcon>
            <ServiceName>{t("home.services.vin.name")}</ServiceName>
            <ServiceDesc>{t("home.services.vin.desc")}</ServiceDesc>
            <ServicePrice>
              {(() => {
                const s = Array.isArray(servicePrices)
                  ? servicePrices.find((x) => x.service === "VIN")
                  : null;
                const isCI =
                  ipCountry === "CI" ||
                  localStorage.getItem("currencyCheck") === "XOF";
                if (!s) return isCI ? "CFA —" : "$ —";
                return isCI
                  ? `CFA ${Number(s.price).toLocaleString()}`
                  : `$${Number(s.price2).toFixed(2)}`;
              })()}
            </ServicePrice>
            <FeatureList>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.vinLookup")}
              </FeatureItem>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.vehicleDetails")}
              </FeatureItem>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.ownershipHistory")}
              </FeatureItem>
              <FeatureItem>
                <FaCheckCircle /> {t("home.services.feature.resultsMinutes")}
              </FeatureItem>
            </FeatureList>
            <ServiceBtn to={vehicleVerify}>
              {t("home.services.verifyNow")}
            </ServiceBtn>
            <LearnMoreLink to="/vehicle-verification">
              {t("home.services.learnMore")}{" "}
              <FaArrowRight style={{ fontSize: 11 }} />
            </LearnMoreLink>
          </ServiceCard>
        </CardsGrid>
      </ServicesSection>

      <NinLoginSample />

      {/* ── Compliance ── */}
      <ComplianceSection>
        <ComplianceInner>
          <ComplianceText>
            <ComplianceTitle>{t("home.compliance.title")}</ComplianceTitle>
            <ComplianceDesc>{t("home.compliance.desc")}</ComplianceDesc>
          </ComplianceText>
          <ComplianceLogos>
            <ComplianceBadge>
              <img src={gdprImg} alt="GDPR" />
            </ComplianceBadge>
            <ComplianceBadge>
              <img src={ndprImg} alt="NDPC" />
            </ComplianceBadge>
            <ComplianceBadge>
              <img src={nimcImg} alt="NCMC" style={{ maxHeight: 48 }} />
            </ComplianceBadge>
            <ComplianceBadge>
              <img src={osiaImg} alt="OSIA" style={{ maxHeight: 48 }} />
            </ComplianceBadge>
          </ComplianceLogos>
        </ComplianceInner>
      </ComplianceSection>

      {/* ── CTA ── */}
      <CtaSection>
        <CtaInner>
          <CtaShield>
            <FaCheckCircle />
          </CtaShield>
          <CtaContent>
            <CtaTitle>{t("home.cta.title")}</CtaTitle>
            <CtaDesc>{t("home.cta.desc")}</CtaDesc>
          </CtaContent>
          <CtaButton to={ctaLink}>{t("home.cta.button")}</CtaButton>
        </CtaInner>
      </CtaSection>

      <div style={{ height: 40 }} />
      <NewsletterSection visible={false} onClose={() => {}} />
    </>
  );
};

export default Home;
